	internal static class RenderTarget
	{
		public static int CreateNamedRenderTargetForModel(string name, Model model)
		{
			int result = 0;
			if (!Function.Call<bool>(Hash.IS_NAMED_RENDERTARGET_REGISTERED, new InputArgument[1] { name }))
			{
				Function.Call(Hash.REGISTER_NAMED_RENDERTARGET, new InputArgument[2] { name, 0 });
			}
			if (!Function.Call<bool>(Hash.IS_NAMED_RENDERTARGET_LINKED, new InputArgument[1] { model.Hash }))
			{
			}
			if (Function.Call<bool>(Hash.IS_NAMED_RENDERTARGET_REGISTERED, new InputArgument[1] { name }))
			{
				result = Function.Call<int>(Hash.GET_NAMED_RENDERTARGET_RENDER_ID, new InputArgument[1] { name });
			}
			return result;
		}
	}

