	public class CustomCameraManager
	{
		private int _CycleInterval = 10000;

		private int nextChange = 0;

		public List<CustomCamera> Cameras { get; private set; } = new List<CustomCamera>();

		public int CurrentCameraIndex { get; private set; } = -1;

		public bool CycleCameras { get; set; } = false;

		public int CycleInterval
		{
			get
			{
				return _CycleInterval;
			}
			set
			{
				if (CycleCameras)
				{
					nextChange -= _CycleInterval;
					nextChange += value;
				}
				_CycleInterval = value;
			}
		}

		public CustomCamera CurrentCamera
		{
			get
			{
				if (CurrentCameraIndex == -1)
				{
					return null;
				}
				return Cameras[CurrentCameraIndex];
			}
		}

		public CustomCamera Add(Entity entity, Vector3 positionOffset, Vector3 pointAtOffset, float fieldOfView)
		{
			CustomCamera customCamera = new CustomCamera(entity, positionOffset, pointAtOffset, fieldOfView);
			Cameras.Add(customCamera);
			return customCamera;
		}

		public void Show(int index, CameraSwitchType cameraSwitchType = CameraSwitchType.Instant)
		{
			if (Cameras.Count != 0 && index <= Cameras.Count - 1 && index >= 0)
			{
				CustomCamera OldCamera = CurrentCamera;
				Cameras[index].Show(ref OldCamera);
				CurrentCameraIndex = index;
			}
		}

		public void ShowNext(CameraSwitchType cameraSwitchType = CameraSwitchType.Instant)
		{
			if (Cameras.Count != 0)
			{
				if (CurrentCameraIndex == Cameras.Count - 1)
				{
					Abort();
					return;
				}
				CustomCamera OldCamera = CurrentCamera;
				Cameras[CurrentCameraIndex + 1].Show(ref OldCamera, cameraSwitchType);
				CurrentCameraIndex++;
			}
		}

		public void ShowPrevious(CameraSwitchType cameraSwitchType = CameraSwitchType.Instant)
		{
			if (Cameras.Count != 0)
			{
				if (CurrentCameraIndex <= 0)
				{
					Abort();
					return;
				}
				CustomCamera OldCamera = CurrentCamera;
				Cameras[CurrentCameraIndex - 1].Show(ref OldCamera, cameraSwitchType);
				CurrentCameraIndex--;
			}
		}

		public void Stop()
		{
			if (CurrentCameraIndex > -1)
			{
				CurrentCamera.Stop();
				CurrentCameraIndex = -1;
			}
		}

		public void Abort()
		{
			Stop();
			Cameras.ForEach((CustomCamera x) =>
			{
				x.Abort();
			});
			World.DestroyAllCameras();
		}

		public void Process()
		{
			if (CycleCameras && nextChange < Game.GameTime)
			{
				ShowNext();
				nextChange = Game.GameTime + CycleInterval;
			}
			if (CurrentCameraIndex > -1 && !CurrentCamera.Camera.IsActive)
			{
				Stop();
			}
		}
	}

	public class CustomCamera
	{
		public Entity Entity { get; private set; }

		public Vector3 PositionOffset { get; private set; }

		public Vector3 PointAtOffset { get; private set; }

		public float FieldOfView { get; private set; }

		public Camera Camera { get; private set; }

		public CustomCamera(Entity entity, Vector3 positionOffset, Vector3 pointAtOffset, float fieldOfView)
		{
			Entity = entity;
			PositionOffset = positionOffset;
			PointAtOffset = pointAtOffset;
			FieldOfView = fieldOfView;
		}

		public void Show(ref CustomCamera OldCamera, CameraSwitchType cameraSwitchType = CameraSwitchType.Instant)
		{
			if (Camera == null || !Camera.Exists())
			{
				Camera = World.CreateCamera(Entity.Position, Entity.Rotation, FieldOfView);
				Camera.AttachTo(Entity, PositionOffset);
				Camera.PointAt(Entity, PointAtOffset);
			}
			if (OldCamera == null || OldCamera.Camera == null || !OldCamera.Camera.Exists())
			{
				World.RenderingCamera = Camera;
				return;
			}
			Camera.IsActive = true;
			OldCamera.Camera.IsActive = false;
			if (cameraSwitchType == CameraSwitchType.Animated)
			{
				OldCamera.Camera.InterpTo(Camera, 900, 1, 1);
			}
			else
			{
				World.RenderingCamera = Camera;
			}
		}

		public void Stop()
		{
			Camera.IsActive = false;
			World.RenderingCamera = null;
		}

		public void Abort()
		{
			if (Camera != null)
			{
				Camera.Delete();
				Camera = null;
			}
		}
	}

