	public static string LoadPedModel(string PedModel)
	{
		while (!Function.Call<bool>(Hash.HAS_MODEL_LOADED, new InputArgument[1] { PedModel }))
		{
			Function.Call(Hash.REQUEST_MODEL, new InputArgument[1] { PedModel });
			Script.Yield();
		}
		return PedModel;
	}

	public static string LoadCutsceneWithFlag(string cutscene, int playbackflag)
	{
		while (!Function.Call<bool>(Hash.HAS_CUTSCENE_LOADED, new InputArgument[1] { cutscene }))
		{
			Function.Call(Hash.REQUEST_CUTSCENE_WITH_PLAYBACK_LIST, new InputArgument[3] { cutscene, playbackflag, 8 });
			Script.Yield();
		}
		return cutscene;
	}

	public static string LoadCutscene(string cutscene)
	{
		while (!Function.Call<bool>(Hash.HAS_CUTSCENE_LOADED, new InputArgument[1] { cutscene }))
		{
			Function.Call(Hash.REQUEST_CUTSCENE, new InputArgument[1] { cutscene });
			Script.Yield();
		}
		return cutscene;
	}

	public static string LoadDict(string dict)
	{
		while (!Function.Call<bool>(Hash.HAS_ANIM_DICT_LOADED, new InputArgument[1] { dict }))
		{
			Function.Call(Hash.REQUEST_ANIM_DICT, new InputArgument[1] { dict });
			Script.Yield();
		}
		return dict;
	}

	public static string LoadStream(string name, string dict)
	{
		while (!Function.Call<bool>(Hash.LOAD_STREAM, new InputArgument[2] { name, dict }))
		{
			Function.Call(Hash.LOAD_STREAM, new InputArgument[2] { name, dict });
			Script.Yield();
		}
		return dict;
	}

	public static string LoadTexureDict(string dict)
	{
		while (!Function.Call<bool>(Hash.HAS_STREAMED_TEXTURE_DICT_LOADED, new InputArgument[1] { dict }))
		{
			Function.Call(Hash.REQUEST_STREAMED_TEXTURE_DICT, new InputArgument[1] { dict });
			Script.Yield();
		}
		return dict;
	}

	public void SetPedOutfitCutscene(string MP, Ped NonCutscene)
	{
		if (MP.Equals("MP_1"))
		{
			CutscenePed1Comp[0] = "0_" + Function.Call<int>(Hash.GET_PED_DRAWABLE_VARIATION, new InputArgument[2] { NonCutscene, 0 }) + "_" + Function.Call<int>(Hash.GET_PED_TEXTURE_VARIATION, new InputArgument[2] { NonCutscene, 0 });
			CutscenePed1Comp[1] = "1_" + Function.Call<int>(Hash.GET_PED_DRAWABLE_VARIATION, new InputArgument[2] { NonCutscene, 1 }) + "_" + Function.Call<int>(Hash.GET_PED_TEXTURE_VARIATION, new InputArgument[2] { NonCutscene, 1 });
