	public void LesterMenu()
	{
		LesterMenu1.Add(LoseCops);
		LesterMenu1.Add(CopsTurnBlindEyeOption);
		if (!LesterIntro)
		{
			return;
		}
		LoseCops.Activated += (object sender, EventArgs e) =>
		{
			if (Wallet >= 5000 && Game.Player.WantedLevel >= 1)
			{
				Wallet -= 5000;
				Config.SetValue("Level", "Wallet", Wallet);
				Config.Save();
				Game.Player.WantedLevel = 0;
				LesterPhoneMenu.HideAll();
			}
			else if (Wallet < 5000)
			{
				Notification.Show("Not Enough Cash");
			}
			else if (Game.Player.WantedLevel == 0)
			{
				Notification.Show("You are not Wanted yet");
			}
		};
		CopsTurnBlindEyeOption.Activated += (object sender, EventArgs e) =>
		{
			if (Wallet >= 12568)
			{
				Wallet -= 12568;
				Config.SetValue("Level", "Wallet", Wallet);
				Config.Save();
				if (Game.MaxWantedLevel == 5)
				{
					Game.MaxWantedLevel = 0;
				}
				CopsTurnBlindEyeswitch = 1;
				LesterPhoneMenu.HideAll();
				CopsBlindEyeBought = true;
			}
			else if (Wallet < 12568)
			{
				Notification.Show("Not Enough Cash");
			}
			else if (CopsBlindEyeBought)
			{
				Notification.Show("You already have this active");
			}
		};
	}

	public void NormalMenus()
	{
		ExitApartment.Activated += (object sender, EventArgs e) =>
		{
			ExitMenuApartment.Visible = false;
			Script.Wait(1000);
			Game.Player.CanControlCharacter = true;
			HudandRadar(Hud: false, Radar: false);
			if (CutsceneCam == null)
			{
				CutsceneCam = Function.Call<Camera>(Hash.CREATE_CAM, new InputArgument[2] { "DEFAULT_ANIMATED_CAMERA", 0 });
			}
			if (CutsceneCam != null)
			{
				World.RenderingCamera = CutsceneCam;
			}
			LoadDict("mp_doorbell");
			LoadDict("mp_doorbell");
			Script.Wait(50);
			Prop[] nearbyProps = World.GetNearbyProps(new Vector3(-778.8248f, 339.8966f, 196.6863f), 5f);
			Prop[] array = nearbyProps;
			foreach (Prop prop in array)
