	public void ApartmentMenus()
	{
		EclipseBuy1.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 1;
		};
		EclipseBuy2.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 2;
		};
		EclipseBuy3.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 3;
		};
		EclipseBuy4.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 4;
		};
		EclipseBuy5.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 5;
		};
		EclipseBuy6.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 6;
		};
		EclipseBuy7.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 7;
		};
		EclipseBuy8.Selected += (object sender, SelectedEventArgs e) =>
		{
			ShowApartment = 8;
		};
		EclipseBuy1.Activated += (object sender, EventArgs e) =>
		{
			if (Wallet >= 600000)
			{
				ApartmentOwned = true;
				Config.SetValue("Player Apartments", "Eclipse Towers", ApartmentOwned);
				Config.Save();
				ApartmentType = 1;
				Config.SetValue("Player Apartments", "Eclipse Towers - Apartment Color", ApartmentType);
				Config.Save();
				Function.Call(Hash.REQUEST_IPL, new InputArgument[1] { "apa_v_mp_h_01_a" });
				Function.Call(Hash.REQUEST_IPL, new InputArgument[1] { "apa_v_mp_h_01_c" });
				Function.Call(Hash.REQUEST_IPL, new InputArgument[1] { "apa_v_mp_h_01_b" });
				Wallet -= 600000;
				Config.SetValue("Level", "Wallet", Wallet);
				Config.Save();
				ShowApartment = 0;
				CharacterMenuOpen = false;
				EclipseMenu.Visible = false;
				CutsceneCam.Delete();
