	public void CharacterMenus()
	{
		GenderItem.ItemChanged += (object sender, ItemChangedEventArgs<string> e) =>
		{
			if (GenderItem.SelectedItem == "Male")
			{
				ApparelMenu.Remove(OutfitFemale);
				ApparelMenu.Remove(HatsFemale);
				ApparelMenu.Remove(Outfit);
				ApparelMenu.Remove(Hats);
				CharacterGender = 1;
				Game.Player.ChangeModel(PedHash.FreemodeMale01);
				TestCutsceneAnim = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE, new InputArgument[7] { 404.9315f, -997.8859f, -98.85f, 0.0, 0.0, -40f, 2 });
				Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, new InputArgument[10]
				{
					Game.Player.Character,
					TestCutsceneAnim,
					LoadDict("mp_character_creation@customise@male_a"),
					"loop",
					0.0,
					0.0,
					0,
					0,
					1148846080,
					0
				});
				Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, new InputArgument[8]
				{
					Game.Player.Character,
					TestCutsceneAnim,
					"loop",
					LoadDict("mp_character_creation@customise@male_a"),
					1000f,
					0f,
					0,
					1000f
				});
				Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, new InputArgument[15]
				{
					MugShotProp,
					Game.Player.Character,
					Game.Player.Character.Bones[Bone.PHRightHand].Index,
					0f,
					0f,
					0f,
					0f,
					0f,
					0f,
					0,
					0,
					0,
					0,
					2,
					1
				});
				Function.Call(Hash.FORCE_ENTITY_AI_AND_ANIMATION_UPDATE, new InputArgument[1] { MugShotProp });
				GetPedOutfitOnline(Game.Player.Character);
				ApparelMenu.Add(Outfit);
				ApparelMenu.Add(Hats);
			}
			if (GenderItem.SelectedItem == "Female")
			{
				ApparelMenu.Remove(Outfit);
				ApparelMenu.Remove(Hats);
				ApparelMenu.Remove(OutfitFemale);
				ApparelMenu.Remove(HatsFemale);
				CharacterGender = 2;
				Game.Player.ChangeModel(PedHash.FreemodeFemale01);
				TestCutsceneAnim = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE, new InputArgument[7] { 404.9315f, -997.8859f, -98.85f, 0.0, 0.0, -40f, 2 });
				Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, new InputArgument[10]
				{
					Game.Player.Character,
					TestCutsceneAnim,
					LoadDict("mp_character_creation@customise@male_a"),
					"loop",
					0.0,
					0.0,
					0,
					0,
					1148846080,
					0
				});
				Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, new InputArgument[8]
				{
					Game.Player.Character,
					TestCutsceneAnim,
					"loop",
					LoadDict("mp_character_creation@customise@male_a"),
					1000f,
					0f,
					0,
					1000f
				});
				Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, new InputArgument[15]
				{
					MugShotProp,
					Game.Player.Character,
					Game.Player.Character.Bones[Bone.PHRightHand].Index,
					0f,
					0f,
					0f,
					0f,
					0f,
					0f,
					0,
					0,
					0,
					0,
					2,
					1
				});
				Function.Call(Hash.FORCE_ENTITY_AI_AND_ANIMATION_UPDATE, new InputArgument[1] { MugShotProp });
				GetPedOutfitOnline(Game.Player.Character);
				ApparelMenu.Add(OutfitFemale);
				ApparelMenu.Add(HatsFemale);
			}
		};
		SaveAndDone.Activated += (object sender, EventArgs e) =>
		{
			CustomisationMenu.Visible = false;
			Function.Call(Hash.SET_CAM_SPLINE_DURATION, new InputArgument[2] { CutsceneCam, 7000 });
			Function.Call(Hash.PLAY_SOUND, new InputArgument[6] { -1, "Zoom_In", "MUGSHOT_CHARACTER_CREATION_SOUNDS", false, 0, true });
			if (!Spline3Set)
			{
				Function.Call(Hash.ADD_CAM_SPLINE_NODE, new InputArgument[10] { CutsceneCam, 402.9284f, -997.7883f, -98.4333f, 0f, 0f, 359.1707f, 1, 100, 0 });
				Spline3Set = true;
			}
			else
			{
				Function.Call(Hash.SET_CAM_SPLINE_PHASE, new InputArgument[2] { CutsceneCam, 1f });
			}
			LoadDict("mp_character_creation@customise@male_a");
			LoadDict("mp_character_creation@customise@male_a");
			Script.Wait(50);
			TestCutsceneAnim = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE, new InputArgument[7] { 404.9315f, -997.8859f, -98.85f, 0.0, 0.0, -40f, 2 });
			Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, new InputArgument[10]
			{
				Game.Player.Character,
				TestCutsceneAnim,
				LoadDict("mp_character_creation@customise@male_a"),
				"outro",
				0.0,
				0.0,
				0,
				0,
				1148846080,
				0
			});
			Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, new InputArgument[8]
			{
				Game.Player.Character,
				TestCutsceneAnim,
				"outro",
				LoadDict("mp_character_creation@customise@male_a"),
				1000f,
				0f,
				0,
				1000f
			});
			Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, new InputArgument[15]
			{
				MugShotProp,
				Game.Player.Character,
				Game.Player.Character.Bones[Bone.PHRightHand].Index,
				0f,
				0f,
				0f,
				0f,
				0f,
				0f,
				0,
				0,
				0,
				0,
				2,
				1
			});
			Function.Call(Hash.FORCE_ENTITY_AI_AND_ANIMATION_UPDATE, new InputArgument[1] { MugShotProp });
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { MugShotBoardCamShutter, "SHOW_REMAINING_PHOTOS" });
			Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_BOOL, new InputArgument[1] { false });
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { MugShotBoardCamShutter, "SHOW_PHOTO_FRAME" });
			Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_BOOL, new InputArgument[1] { true });
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { MugShotBoardCamShutter, "SHOW_PHOTO_BORDER" });
			Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_BOOL, new InputArgument[1] { false });
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { MugShotBoardCamShutter, "OPEN_SHUTTER" });
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			CharacterCustomizationswitch = 4;
		};
