		Features.Activated += (object sender, EventArgs e) =>
		{
			if (CutsceneCam != null)
			{
				SafeMenu.Select(Feature1, FaceFeaturePart);
				SafeMenu.Select(Feature2, FaceFeaturePart1);
				SafeMenu.Select(Feature3, FaceFeaturePart2);
				SafeMenu.Select(Feature4, FaceFeaturePart3);
				SafeMenu.Select(Feature5, FaceFeaturePart4);
				SafeMenu.Select(Feature6, FaceFeaturePart5);
				SafeMenu.Select(Feature7, FaceFeaturePart6);
				SafeMenu.Select(Feature8, FaceFeaturePart7);
				SafeMenu.Select(Feature9, FaceFeaturePart8);
				SafeMenu.Select(Feature10, FaceFeaturePart9);
				SafeMenu.Select(Feature11, FaceFeaturePart10);
				SafeMenu.Select(Feature12, FaceFeaturePart11);
				SafeMenu.Select(Feature13, FaceFeaturePart12);
				SafeMenu.Select(Feature14, FaceFeaturePart13);
				SafeMenu.Select(Feature15, FaceFeaturePart14);
				SafeMenu.Select(Feature16, FaceFeaturePart15);
				SafeMenu.Select(Feature17, FaceFeaturePart16);
				SafeMenu.Select(Feature18, FaceFeaturePart17);
				SafeMenu.Select(Feature19, FaceFeaturePart18);
				SafeMenu.Select(Feature20, FaceFeaturePart19);
				Function.Call(Hash.PLAY_SOUND, new InputArgument[6] { -1, "Zoom_In", "MUGSHOT_CHARACTER_CREATION_SOUNDS", false, 0, true });
				Function.Call(Hash.SET_CAM_SPLINE_DURATION, new InputArgument[2] { CutsceneCam, 15000 });
				if (!Spline1Set)
				{
					Function.Call(Hash.ADD_CAM_SPLINE_NODE, new InputArgument[10] { CutsceneCam, 402.8284f, -997.5883f, -98.4333f, 0f, 0f, 359.1707f, 1, 100, 0 });
					Spline1Set = true;
				}
				else
				{
					Function.Call(Hash.SET_CAM_SPLINE_PHASE, new InputArgument[2] { CutsceneCam, 0.5f });
				}
			}
			FeatureMenu.Visible = true;
		};
		Features.Menu.Closed += (object sender, EventArgs e) =>
		{
			if (CutsceneCam != null)
			{
				Function.Call(Hash.PLAY_SOUND, new InputArgument[6] { -1, "Zoom_Out", "MUGSHOT_CHARACTER_CREATION_SOUNDS", false, 0, true });
				Function.Call(Hash.SET_CAM_SPLINE_DURATION, new InputArgument[2] { CutsceneCam, -1 });
				Function.Call(Hash.SET_CAM_SPLINE_PHASE, new InputArgument[2] { CutsceneCam, 0.3f });
			}
		};
