		Appearance.Activated += (object sender, EventArgs e) =>
		{
			if (CutsceneCam != null)
			{
				SafeMenu.Select(Hair, HairString);
				SafeMenu.Select(HairColors, HairColor);
				SafeMenu.Select(EyeBrow, EyeBrowString);
				SafeMenu.Select(EyeBrowColors, OverlayColorPart2);
				SafeMenu.Select(EyeBrowAlpha, OverlayPart15);
				SafeMenu.Select(FacialHair, FacialHairString);
				SafeMenu.Select(FacialHairColors, OverlayColorPart1);
				SafeMenu.Select(FacialHairAlpha, OverlayPart14);
				SafeMenu.Select(Blemishes, BlemishesString);
				SafeMenu.Select(BlemishesAlpha, OverlayPart13);
				Function.Call(Hash.PLAY_SOUND, new InputArgument[6] { -1, "Zoom_In", "MUGSHOT_CHARACTER_CREATION_SOUNDS", false, 0, true });
				Function.Call(Hash.SET_CAM_SPLINE_DURATION, new InputArgument[2] { CutsceneCam, 15000 });
				if (!Spline1Set)
				{
					Function.Call(Hash.ADD_CAM_SPLINE_NODE, new InputArgument[10] { CutsceneCam, 402.8284f, -997.5883f, -98.4333f, 0f, 0f, 359.1707f, 1, 100, 0 });
					Spline1Set = true;
				}
				else
				{
					Function.Call(Hash.SET_CAM_SPLINE_PHASE, new InputArgument[2] { CutsceneCam, 0.5f });
				}
			}
			AppearanceMenu.Visible = true;
		};
		Appearance.Menu.Closed += (object sender, EventArgs e) =>
		{
			if (CutsceneCam != null)
			{
				Function.Call(Hash.PLAY_SOUND, new InputArgument[6] { -1, "Zoom_Out", "MUGSHOT_CHARACTER_CREATION_SOUNDS", false, 0, true });
				Function.Call(Hash.SET_CAM_SPLINE_DURATION, new InputArgument[2] { CutsceneCam, -1 });
				Function.Call(Hash.SET_CAM_SPLINE_PHASE, new InputArgument[2] { CutsceneCam, 0.3f });
			}
		};
		Hair.ItemChanged += (object sender, ItemChangedEventArgs<string> e) =>
