		Apparel.Activated += (object sender, EventArgs e) =>
		{
			if (CutsceneCam != null)
			{
				Function.Call(Hash.PLAY_SOUND, new InputArgument[6] { -1, "Zoom_In", "MUGSHOT_CHARACTER_CREATION_SOUNDS", false, 0, true });
				Function.Call(Hash.SET_CAM_SPLINE_DURATION, new InputArgument[2] { CutsceneCam, -1 });
				Function.Call(Hash.SET_CAM_SPLINE_PHASE, new InputArgument[2] { CutsceneCam, 0.4f });
			}
			LoadDict("mp_character_creation@customise@male_a");
			LoadDict("mp_character_creation@customise@male_a");
			Script.Wait(50);
			TestCutsceneAnim = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE, new InputArgument[7]
			{
				Game.Player.Character.Position.X,
				Game.Player.Character.Position.Y,
				Game.Player.Character.Position.Z,
				0.0,
				0.0,
				180f,
				2
			});
			Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, new InputArgument[10]
			{
				Game.Player.Character,
				TestCutsceneAnim,
				LoadDict("mp_character_creation@customise@male_a"),
				"drop_intro",
				0.0,
				0.0,
				0,
				0,
				1148846080,
				0
			});
			Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, new InputArgument[8]
			{
				Game.Player.Character,
				TestCutsceneAnim,
				"drop_intro",
				LoadDict("mp_character_creation@customise@male_a"),
				1000f,
				0f,
				0,
				1000f
			});
			Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, new InputArgument[15]
			{
				MugShotProp,
				Game.Player.Character,
				Game.Player.Character.Bones[Bone.PHRightHand].Index,
				0f,
				0f,
				0f,
				0f,
				0f,
				0f,
				0,
				0,
				0,
				0,
				2,
				1
			});
			Function.Call(Hash.FORCE_ENTITY_AI_AND_ANIMATION_UPDATE, new InputArgument[1] { MugShotProp });
			ApparelMenu.Visible = true;
			CharacterCustomizationswitch = 5;
		};
