		ReadyToPlay.Activated += (object sender, EventArgs e) =>
		{
			HeistOutfitMenu1.Visible = false;
			Function.Call(Hash.CLEAR_TIMECYCLE_MODIFIER, Array.Empty<InputArgument>());
			FuckOffCivilians = true;
			NoCopsOnMission = true;
			Function.Call(Hash.TRIGGER_SCREENBLUR_FADE_IN, new InputArgument[1] { 1f });
			Function.Call(Hash.SET_TIME_SCALE, new InputArgument[1] { 0f });
			MPApartmentLoads();
			Function.Call(Hash.SET_WEATHER_TYPE_NOW_PERSIST, new InputArgument[1] { "EXTRASUNNY" });
			Function.Call(Hash.SET_CLOCK_TIME, new InputArgument[3] { 0, 0, 0 });
			Function.Call(Hash.PAUSE_CLOCK, new InputArgument[1] { true });
			HudandRadar(Hud: false, Radar: false);
			Function.Call(Hash.CLEAR_ALL_HELP_MESSAGES, Array.Empty<InputArgument>());
			Function.Call(Hash.ANIMPOSTFX_PLAY, new InputArgument[3] { "MP_job_load", 0, false });
			Function.Call(Hash.START_AUDIO_SCENE, new InputArgument[1] { "CREATOR_SCENES_AMBIENCE" });
			Game.Player.Character.IsPositionFrozen = true;
			Function.Call(Hash.PLAY_SOUND_FRONTEND, new InputArgument[4] { -1, "SCREEN_FLASH", "CELEBRATION_SOUNDSET", true });
			LoadingPrompt.Show("Loading Session");
			Script.Wait(6000);
			Function.Call(Hash.TRIGGER_MUSIC_EVENT, new InputArgument[1] { "MP_MC_START_HEIST_PREP_NEW" });
			Function.Call(Hash.TRIGGER_MUSIC_EVENT, new InputArgument[1] { "MP_MC_SUSPENSE_HPREP" });
			Script.Wait(3000);
			if (CutsceneCam != null)
			{
				CutsceneCam.Delete();
				CutsceneCam = null;
				World.RenderingCamera = null;
			}
			if (CutsceneCam == null)
			{
				CutsceneCam = Function.Call<Camera>(Hash.CREATE_CAM, new InputArgument[2] { "DEFAULT_ANIMATED_CAMERA", 0 });
			}
			Game.Player.Character.Position = new Vector3(-775.3641f, 317.8808f, 85.65843f);
			AtHeistBoard = false;
			LoadingPrompt.Hide();
			GetPedMaskOffOnline();
			Function.Call(Hash.ANIMPOSTFX_STOP_ALL, Array.Empty<InputArgument>());
			LoadDict("ANIM@MP_APT_EXT@EXIT_ALL");
			LoadDict("ANIM@MP_APT_EXT@EXIT_ALL");
			Script.Wait(50);
			Prop[] nearbyProps = World.GetNearbyProps(new Vector3(-776.6961f, 312.8342f, 85.69812f), 50f, RequestModel(100848840));
			Prop[] array = nearbyProps;
			foreach (Prop prop in array)
			{
				TestCutsceneAnim = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE, new InputArgument[7]
				{
					prop.Position.X,
					prop.Position.Y,
					prop.Position.Z,
					0.0,
					0.0,
					0f,
					2
				});
				Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, new InputArgument[10]
				{
					Game.Player.Character,
					TestCutsceneAnim,
					LoadDict("ANIM@MP_APT_EXT@EXIT_ALL"),
					"apt_exit_right_ped_a",
					0.0,
					0.0,
					0,
					0,
					1148846080,
					0
				});
				Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, new InputArgument[8]
				{
					Game.Player.Character,
					TestCutsceneAnim,
					"apt_exit_right_ped_a",
					LoadDict("ANIM@MP_APT_EXT@EXIT_ALL"),
					1000f,
					0f,
					0,
					1000f
				});
				Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, new InputArgument[10]
				{
					prop,
					TestCutsceneAnim,
					LoadDict("ANIM@MP_APT_EXT@EXIT_ALL"),
					"apt_exit_right_r_door",
					0.0,
					0.0,
					0,
					0,
					1148846080,
					0
				});
				Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, new InputArgument[8]
				{
					prop,
					TestCutsceneAnim,
					"apt_exit_right_r_door",
					LoadDict("ANIM@MP_APT_EXT@EXIT_ALL"),
					1000f,
					0f,
					0,
					1000f
				});
				Function.Call(Hash.PLAY_CAM_ANIM, new InputArgument[11]
				{
					CutsceneCam,
					"apt_exit_right_safecam",
					LoadDict("ANIM@MP_APT_EXT@EXIT_ALL"),
					prop.Position.X,
					prop.Position.Y,
					prop.Position.Z,
					0f,
					0f,
					prop.Heading,
					false,
					2
				});
				if (CutsceneCam != null)
				{
					World.RenderingCamera = CutsceneCam;
				}
				Function.Call(Hash.SET_TIME_SCALE, new InputArgument[1] { 1f });
				Function.Call(Hash.TRIGGER_SCREENBLUR_FADE_OUT, new InputArgument[1] { 1f });
				fleecaProgress = fleecaState.flashsound2;
				missionProgress = missionState.OnDLCMission;
			}
		};
