	public unsafe void onTick(object sender, EventArgs e)
	{
		if (ContinueOnlineOffline)
		{
			ShowApartmentView();
			if (CustomizationChar == null)
			{
				CustomizationChar = World.CreateBlip(new Vector3(-1047.505f, -2743.424f, 21.3594f));
			}
			if (CustomizationChar != null)
			{
				CustomizationChar.Sprite = BlipSprite.Clothes;
				CustomizationChar.Color = BlipColor.Purple;
				CustomizationChar.Name = "Customize Character";
			}
			if (!InCharacterCustomization)
			{
				if (Game.Player.Character.Position.DistanceTo(CustomizationChar.Position) < 100f)
				{
					World.DrawMarker(MarkerType.Cylinder, new Vector3(CustomizationChar.Position.X, CustomizationChar.Position.Y, CustomizationChar.Position.Z - 1f), Vector3.Zero, Vector3.Zero, new Vector3(2f, 2f, 1f), Color.Blue);
					SimeonText2.CallFunction("SET_MISSION_INFO", "Customise Character", "~w~GTA ~r~ONLINE~w~ - ~p~OFFLINE~w~", 0, "", "", 0);
					SimeonText2.Render3D(CustomizationChar.Position + new Vector3(0f, 0f, 0f), new Vector3(1f, 180f, 330.0215f), new Vector3(3f, 2f, 2f));
				}
				if (Game.Player.Character.Position.DistanceTo(CustomizationChar.Position) < 1f)
				{
					if (Game.GameTime > lastHelpTime + helpInterval)
					{
						lastHelpTime = Game.GameTime;
						DisplayHelpText("Press ~INPUT_CONTEXT~ to Customise Your Character for GTA ~r~ONLINE~w~ - ~p~OFFLINE");
					}
					if (Game.IsControlJustPressed(GTA.Control.Context))
					{
						GTA.UI.Screen.FadeOut(1000);
						Script.Wait(3000);
						HudandRadar(Hud: false, Radar: false);
						Game.Player.Character.Position = new Vector3(405.3507f, -997.067f, -99.00404f);
						Script.Wait(1);
						GTA.UI.Screen.FadeIn(500);
						Function.Call(Hash.SET_CLOCK_TIME, new InputArgument[3] { 21, 0, 0 });
						Function.Call(Hash.PAUSE_CLOCK, new InputArgument[1] { true });
						CharacterCustomizationswitch = 1;
						InCharacterCustomization = true;
					}
				}
			}
			Audio.SetAudioFlag(AudioFlags.LoadMPData, toggle: true);
			if (MugshotTextID == null)
			{
				MugshotTextID = World.CreateProp(RequestModel("prop_police_id_text"), new Vector3(-1010.835f, -2757.618f, 44.46671f), dynamic: false, placeOnGround: false);
			}
			if (MugShotProp == null)
			{
				MugShotProp = World.CreateProp(RequestModel("prop_police_id_board"), new Vector3(-1010.835f, -2757.618f, 44.46671f), dynamic: false, placeOnGround: false);
			}
			if (MugshotTextID != null && MugShotProp != null)
			{
				MugshotTextID.IsVisible = true;
				MugShotProp.IsVisible = true;
				MugshotTextID.IsCollisionEnabled = false;
				MugShotProp.IsCollisionEnabled = false;
				MugshotTextID.IsPositionFrozen = true;
				MugShotProp.IsPositionFrozen = true;
				MugshotTextID.AttachTo(MugShotProp, new Vector3(0f, 0f, 0f), new Vector3(0f, 0f, 0f));
			}
			if (VLPed == null)
			{
				VLPed = World.CreatePed(PedHash.LesterCrest, Game.Player.Character.Position);
			}
			if (VLPed != null)
			{
				VLPed.IsVisible = false;
				VLPed.BlockPermanentEvents = true;
				VLPed.AlwaysKeepTask = true;
				VLPed.IsInvincible = true;
				Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, new InputArgument[15]
				{
					VLPed,
					Game.Player.Character,
					Game.Player.Character.Bones[500].Index,
					0f,
