					Config.Save();
					PhoneRing.Play();
					Script.Wait(3000);
					if (VLPed != null)
					{
						Function.Call(Hash.CREATE_NEW_SCRIPTED_CONVERSATION, Array.Empty<InputArgument>());
						Function.Call(Hash.ADD_PED_TO_CONVERSATION, new InputArgument[3] { 0, VLPed, "lester" });
						Function.Call(Hash.ADD_LINE_TO_CONVERSATION, new InputArgument[13]
						{
							0, "lc_akaa", "lester", 1, 1, 1, 1, 1, 1, 0,
							0, 1, 1
						});
						Function.Call(Hash.ADD_LINE_TO_CONVERSATION, new InputArgument[13]
						{
							0, "lc_akab", "lester", 1, 1, 1, 1, 1, 1, 0,
							0, 1, 1
						});
						Function.Call(Hash.ADD_LINE_TO_CONVERSATION, new InputArgument[13]
						{
							0, "lc_akac", "lester", 1, 1, 1, 1, 1, 1, 0,
							0, 1, 1
						});
						Function.Call(Hash.START_SCRIPT_PHONE_CONVERSATION, new InputArgument[2] { 0, 0 });
					}
					fleecaProgress = fleecaState.fleecaNotStarted;
				}
				break;
			}
		}
		else
		{
			if (Leftoff == null)
			{
				Leftoff = World.CreateBlip(new Vector3(-1042.637f, -2745.901f, 21.35938f));
			}
			if (Leftoff != null)
			{
				Leftoff.Sprite = BlipSprite.Omega;
				Leftoff.Color = BlipColor.Purple;
				Leftoff.Name = "Continue GTA ONLINE - OFFLINE";
			}
			if (Game.Player.Character.Position.DistanceTo(Leftoff.Position) < 100f)
			{
				World.DrawMarker(MarkerType.Cylinder, new Vector3(-1042.637f, -2745.901f, 20.35938f), Vector3.Zero, Vector3.Zero, new Vector3(2f, 2f, 1f), Color.Blue);
				TrevorText1.CallFunction("SET_MISSION_INFO", "Continue where you left off?", "~w~GTA ~r~ONLINE~w~ - ~p~OFFLINE~w~", 0, "", "", 0);
				TrevorText1.Render3D(Leftoff.Position + new Vector3(0f, 0f, 0f), new Vector3(1f, 180f, 330.0215f), new Vector3(3f, 2f, 2f));
			}
			if (Game.Player.Character.Position.DistanceTo(Leftoff.Position) < 1f)
			{
				if (Game.GameTime > lastHelpTime + helpInterval)
				{
					lastHelpTime = Game.GameTime;
					DisplayHelpText("Press ~INPUT_CONTEXT~ to Continue where you left off in GTA ~r~ONLINE~w~ - ~p~OFFLINE");
				}
				if (Game.IsControlJustPressed(GTA.Control.Context))
				{
					DrawPlayerListScaleform();
					Function.Call(Hash.CLEAR_ALL_HELP_MESSAGES, Array.Empty<InputArgument>());
					if (CharacterGender == 1)
					{
						Game.Player.ChangeModel(PedHash.FreemodeMale01);
					}
					if (CharacterGender == 2)
					{
						Game.Player.ChangeModel(PedHash.FreemodeFemale01);
					}
					GetPedOutfitOnline(Game.Player.Character);
					if (Leftoff != null)
					{
						Leftoff.Delete();
					}
					LoadIniFile("Scripts\\GTAOnline_Offline.ini");
					Function.Call(Hash.SET_INSTANCE_PRIORITY_MODE, new InputArgument[1] { true });
					Function.Call(Hash.ON_ENTER_SP, Array.Empty<InputArgument>());
					Function.Call(Hash.ON_ENTER_MP, Array.Empty<InputArgument>());
					GlobalVariable.Get(4).Write(1);
					Function.Call(Hash.TERMINATE_ALL_SCRIPTS_WITH_THIS_NAME, new InputArgument[1] { "respawn_controller" });
					Function.Call(Hash.DISABLE_HOSPITAL_RESTART, new InputArgument[2] { 0, true });
					Function.Call(Hash.DISABLE_HOSPITAL_RESTART, new InputArgument[2] { 1, true });
					Function.Call(Hash.DISABLE_HOSPITAL_RESTART, new InputArgument[2] { 2, true });
					Function.Call(Hash.DISABLE_HOSPITAL_RESTART, new InputArgument[2] { 3, true });
					Function.Call(Hash.DISABLE_HOSPITAL_RESTART, new InputArgument[2] { 4, true });
					Function.Call(Hash.DISABLE_POLICE_RESTART, new InputArgument[2] { 0, true });
					Function.Call(Hash.DISABLE_POLICE_RESTART, new InputArgument[2] { 1, true });
					Function.Call(Hash.DISABLE_POLICE_RESTART, new InputArgument[2] { 2, true });
					Function.Call(Hash.DISABLE_POLICE_RESTART, new InputArgument[2] { 3, true });
					Function.Call(Hash.DISABLE_POLICE_RESTART, new InputArgument[2] { 4, true });
					Function.Call(Hash.DISABLE_POLICE_RESTART, new InputArgument[2] { 5, true });
					Function.Call(Hash.DISABLE_POLICE_RESTART, new InputArgument[2] { 6, true });
					foreach (string removeOnlyIPL2 in RemoveOnlyIPLS)
					{
						Function.Call(Hash.REMOVE_IPL, new InputArgument[1] { removeOnlyIPL2 });
					}
					foreach (string loadAllIPL2 in LoadAllIPLS)
					{
						Function.Call(Hash.REMOVE_IPL, new InputArgument[1] { loadAllIPL2 });
						Function.Call(Hash.REQUEST_IPL, new InputArgument[1] { loadAllIPL2 });
					}
					ContinueOnlineOffline = true;
				}
			}
		}
		if (Function.Call<string>(Hash.GET_PLAYER_NAME, Array.Empty<InputArgument>()) == "TheMonkeyMafia69")
		{
			GoodPlayer("TheMonkeyMafia69", "Hello ThatNuttySquirrel heres your reward for signing up to the newswire and being the nut", "$250,000", 250000);
