	private void VehicleDamageLessCheck()
	{
		if (Kuruma != null)
		{
			if (Kuruma.Health >= 900)
			{
				KurumaHealthElite = 0;
			}
			else if (Kuruma.Health >= 800)
			{
				KurumaHealthElite = 1;
			}
			else if (Kuruma.Health >= 700)
			{
				KurumaHealthElite = 2;
			}
			else if (Kuruma.Health >= 600)
			{
				KurumaHealthElite = 3;
			}
			else if (Kuruma.Health >= 500)
			{
				KurumaHealthElite = 4;
			}
			else if (Kuruma.Health >= 400)
			{
				KurumaHealthElite = 5;
			}
			else if (Kuruma.Health >= 300)
			{
				KurumaHealthElite = 6;
			}
			else if (Kuruma.Health >= 200)
			{
				KurumaHealthElite = 7;
			}
			else if (Kuruma.Health >= 100)
			{
				KurumaHealthElite = 8;
			}
			else if (Kuruma.Health >= 0)
			{
				KurumaHealthElite = 9;
			}
		}
	}

	public bool EliteIfDied()
	{
