	private void EliteTimeCheckSet()
	{
		if (EliteChallengeTimerSec >= 60)
		{
			EliteChallengeTimerSec = 0;
			EliteChallengeTimerMin++;
		}
		if (Game.GameTime > SecTime)
		{
			EliteChallengeTimerSec++;
			SecTime = Game.GameTime + 1000;
		}
	}

