	private void GoodPlayer(string PlayerName, string reasonofGoodness, string reward, int actualreward)
	{
		switch (RewardSwitch)
		{
		case 0:
			if (Function.Call<bool>(Hash.APP_HAS_LINKED_SOCIAL_CLUB_ACCOUNT, Array.Empty<InputArgument>()))
			{
				if (Function.Call<string>(Hash.GET_PLAYER_NAME, Array.Empty<InputArgument>()) == PlayerName)
				{
					RewardSwitch = 1;
				}
				else
				{
					RewardSwitch = 0;
				}
			}
			break;
		case 1:
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { QuestionText, "SHOW_POPUP_WARNING" });
			func_236("");
			func_236("ALERT");
			func_236(PlayerName + " - You have been Rewarded " + reward + " in GTA ONLINE - OFFLINE:~n~ " + reasonofGoodness);
			func_236("");
			ScaleformBOOL(uParam0: true);
			ScaleformBOOL(uParam0: false);
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			RewardSwitch = 2;
			break;
		case 2:
		{
			Function.Call(Hash.DRAW_SCALEFORM_MOVIE, new InputArgument[9] { QuestionText, 0.5f, 0.5f, 1f, 1f, 255, 255, 255, 255 });
			Scaleform scaleform = new Scaleform("instructional_buttons");
			scaleform.CallFunction("CLEAR_ALL");
			scaleform.CallFunction("TOGGLE_MOUSE_BUTTONS", 0);
			scaleform.CallFunction("CREATE_CONTAINER");
			scaleform.CallFunction("SET_DATA_SLOT", 0, Function.Call<string>(Hash.GET_CONTROL_INSTRUCTIONAL_BUTTONS_STRING, new InputArgument[3] { 2, 201, 0 }), "Accept Gift");
			scaleform.CallFunction("DRAW_INSTRUCTIONAL_BUTTONS", -1);
			scaleform.Render2D();
			if (Game.IsControlJustPressed(GTA.Control.FrontendAccept))
			{
				Wallet += actualreward;
				Config.SetValue("Level", "Wallet", Wallet);
				Config.Save();
				Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { QuestionText, "HIDE_POPUP_WARNING" });
				Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
				RewardSwitch = -1;
			}
			break;
		}
		}
	}

