	private void DeathMissionReset(Vector3 firstcheckpoint, Vector3 secondcheckpoint, Vector3 thirdcheckpoint)
	{
		if (!DeadReset)
		{
			if (Game.Player.Character.IsDead)
			{
				TeamLives--;
				int num = 0;
				switch (Function.Call<int>(Hash.GET_RANDOM_INT_IN_RANGE, new InputArgument[2] { 0, 3 }))
				{
				case 0:
					TriggerDeathMission(firstcheckpoint);
					break;
				case 1:
					TriggerDeathMission(secondcheckpoint);
					break;
				case 2:
					TriggerDeathMission(thirdcheckpoint);
					break;
				}
				DeadReset = true;
			}
		}
		else if (Game.Player.Character.IsAlive)
		{
			DeadReset = false;
		}
	}

	private void DeathMissionReset2(Vector3 firstcheckpoint, Vector3 secondcheckpoint, Vector3 thirdcheckpoint, int hours, int minutes, int seconds)
	{
		if (!DeadReset)
		{
			if (Game.Player.Character.IsDead)
			{
				TeamLives--;
				int num = 0;
				switch (Function.Call<int>(Hash.GET_RANDOM_INT_IN_RANGE, new InputArgument[2] { 0, 3 }))
				{
				case 0:
					TriggerDeathMission2(firstcheckpoint, hours, minutes, seconds);
					break;
				case 1:
					TriggerDeathMission2(secondcheckpoint, hours, minutes, seconds);
					break;
				case 2:
					TriggerDeathMission2(thirdcheckpoint, hours, minutes, seconds);
					break;
				}
				DeadReset = true;
			}
		}
		else if (Game.Player.Character.IsAlive)
		{
			DeadReset = false;
		}
	}

	private void TeamLiveShow()
	{
		if (MissionFailswitch == 1)
		{
			drawSprite2("timerbars", "all_black_bg", 0.89f, 0.97f, 0.21f, 0.04f, 255, 255, 255, 130);
			drawText("Team Lives :             " + TeamLives, 0.83f, 0.954f, 0.5f, 255, 255, 255);
