	private void TriggerDeath()
	{
		Audio.PlaySoundFrontend("MP_Flash", "WastedSounds");
		GameplayCamera.Shake(CameraShake.DeathFail, 1.5f);
		GTA.UI.Screen.StartEffect(ScreenEffect.DeathFailMpIn);
		Function.Call(Hash.SET_TIME_SCALE, new InputArgument[1] { 1f });
		Script.Wait(7500);
		GTA.UI.Screen.FadeIn(500);
		Game.Player.Character.IsPositionFrozen = false;
		GTA.UI.Screen.StopEffects();
		GameplayCamera.StopShaking();
		Function.Call(Hash.SET_TIME_SCALE, new InputArgument[1] { 1f });
		HudandRadar(Hud: true, Radar: true);
		GTA.UI.Screen.FadeIn(500);
	}

	private void TriggerDeathMission(Vector3 playerrespawnpoint)
	{
		Audio.PlaySoundFrontend("MP_Flash", "WastedSounds");
		GameplayCamera.Shake(CameraShake.DeathFail, 1.5f);
		GTA.UI.Screen.StartEffect(ScreenEffect.DeathFailMpIn);
		Script.Wait(7500);
		GTA.UI.Screen.FadeIn(500);
		Game.Player.Character.IsInvincible = true;
		GTA.UI.Screen.StopEffects();
		GameplayCamera.StopShaking();
		HudandRadar(Hud: true, Radar: true);
		Game.Player.Character.IsInvincible = false;
		Game.Player.Character.Position = playerrespawnpoint;
		GTA.UI.Screen.FadeIn(500);
	}

	private void TriggerDeathMission2(Vector3 playerrespawnpoint, int hours, int minutes, int seconds)
	{
		Audio.PlaySoundFrontend("MP_Flash", "WastedSounds");
		GameplayCamera.Shake(CameraShake.DeathFail, 1.5f);
		GTA.UI.Screen.StartEffect(ScreenEffect.DeathFailMpIn);
		Script.Wait(7500);
		GTA.UI.Screen.FadeIn(500);
		Function.Call(Hash.SET_CLOCK_TIME, new InputArgument[3] { hours, minutes, seconds });
		Game.Player.Character.IsInvincible = true;
		GTA.UI.Screen.StopEffects();
		GameplayCamera.StopShaking();
		HudandRadar(Hud: true, Radar: true);
		Game.Player.Character.IsInvincible = false;
		Game.Player.Character.Position = playerrespawnpoint;
		GTA.UI.Screen.FadeIn(500);
	}

