	private unsafe void DeletePlayerListScaleform()
	{
		int num = PlayerList;
		Function.Call(Hash.SET_SCALEFORM_MOVIE_AS_NO_LONGER_NEEDED, new InputArgument[1] { &num });
		PlayerList = 0;
		Function.Call(Hash.UNREGISTER_PEDHEADSHOT, new InputArgument[1] { num });
		num = 0;
		Script.Yield();
		PlayerList = Function.Call<int>(Hash.REQUEST_SCALEFORM_MOVIE, new InputArgument[1] { "MP_MM_CARD_FREEMODE" });
		handle = Function.Call<int>(Hash.REGISTER_PEDHEADSHOT, new InputArgument[1] { Game.Player.Character });
	}

	private void DrawPlayerListScaleform()
	{
		switch (PlayerListswtich)
		{
		case 0:
			DeletePlayerListScaleform();
			PlayerListswtich = 1;
