			Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_INT, new InputArgument[1] { 1 });
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
