				ScaleformINT(0);
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { "JobPoints" });
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { text });
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { text });
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { "C" });
				Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			}
			else
			{
				Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { PlayerList, "SET_TITLE" });
				func_string_parm("GTA OFFLINE (Public, 10)");
				func_string_parm("(1)");
				func_string_parm("2");
				Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
				Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { PlayerList, "SET_DATA_SLOT" });
				ScaleformINT(0);
				ScaleformINT(Rank);
				func_string_parm(Player_Name ?? "");
				ScaleformINT(111);
				ScaleformINT(65);
				func_string_parm("");
				func_string_parm(JobPoints.ToString() ?? "");
				ScaleformINT(0);
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { "JobPoints" });
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { text });
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { text });
				Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_TEXTURE_NAME_STRING, new InputArgument[1] { "C" });
				Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			}
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { PlayerList, "DISPLAY_VIEW" });
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			if (Function.Call<bool>(Hash.IS_PEDHEADSHOT_READY, new InputArgument[1] { handle }))
			{
				PlayerListswtich = 2;
			}
			break;
		}
		case 2:
			Function.Call(Hash.SET_SCRIPT_GFX_DRAW_ORDER, new InputArgument[1] { 7 });
			Function.Call(Hash.DRAW_SCALEFORM_MOVIE, new InputArgument[10] { PlayerList, 0.12f, 0.3f, 0.28f, 0.6f, 255, 255, 255, 255, 0 });
