		PedDrawableProp2 = Function.Call<int>(Hash.GET_PED_PROP_INDEX, new InputArgument[2]
		{
			Game.Player.Character,
			2
		});
		PedTextureProp2 = Function.Call<int>(Hash.GET_PED_PROP_TEXTURE_INDEX, new InputArgument[2]
		{
			Game.Player.Character,
			2
		});
		PedDrawableProp3 = Function.Call<int>(Hash.GET_PED_PROP_INDEX, new InputArgument[2]
		{
			Game.Player.Character,
			6
		});
		PedTextureProp3 = Function.Call<int>(Hash.GET_PED_PROP_TEXTURE_INDEX, new InputArgument[2]
		{
			Game.Player.Character,
			6
		});
		PedDrawableProp4 = Function.Call<int>(Hash.GET_PED_PROP_INDEX, new InputArgument[2]
		{
			Game.Player.Character,
			7
		});
		PedTextureProp4 = Function.Call<int>(Hash.GET_PED_PROP_TEXTURE_INDEX, new InputArgument[2]
		{
			Game.Player.Character,
			7
		});
		Config.SetValue("Character Customization", "Head Component 0_1", PedDrawableProp);
		Config.Save();
		Config.SetValue("Character Customization", "Head Component 0_2", PedTextureProp);
		Config.Save();
		Config.SetValue("Character Customization", "Head Component 1_1", PedDrawableProp1);
		Config.Save();
		Config.SetValue("Character Customization", "Head Component 1_2", PedTextureProp1);
		Config.Save();
		Config.SetValue("Character Customization", "Head Component 2_1", PedDrawableProp2);
		Config.Save();
		Config.SetValue("Character Customization", "Head Component 2_2", PedTextureProp2);
