		Config.Save();
		Config.SetValue("Character Customization", "Head Component 7_1", PedDrawableProp4);
		Config.Save();
		Config.SetValue("Character Customization", "Head Component 7_2", PedTextureProp4);
		Config.Save();
	}

	public void GetPlayerHeadProp(Ped NonCutscene)
	{
		LoadIniFile("scripts\\GTAOnline_Offline.ini");
		Function.Call(Hash.CLEAR_ALL_PED_PROPS, new InputArgument[1] { Game.Player.Character });
		Function.Call(Hash.SET_PED_PROP_INDEX, new InputArgument[5] { NonCutscene, 0, PedDrawableProp, PedTextureProp, true });
		Function.Call(Hash.SET_PED_PROP_INDEX, new InputArgument[5] { NonCutscene, 1, PedDrawableProp1, PedTextureProp1, true });
		Function.Call(Hash.SET_PED_PROP_INDEX, new InputArgument[5] { NonCutscene, 2, PedDrawableProp2, PedTextureProp2, true });
		Function.Call(Hash.SET_PED_PROP_INDEX, new InputArgument[5] { NonCutscene, 6, PedDrawableProp3, PedTextureProp3, true });
		Function.Call(Hash.SET_PED_PROP_INDEX, new InputArgument[5] { NonCutscene, 7, PedDrawableProp4, PedTextureProp4, true });
	}

	public void SetPlayerHeadPropEmpty(Ped NonCutscene)
	{
		Function.Call(Hash.CLEAR_ALL_PED_PROPS, new InputArgument[1] { Game.Player.Character });
	}

