	public void GetPedWeaponSelectionOnline(Ped NonCutscene)
	{
		if (WeaponString == "Pistol")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.Pistol, equipNow: true);
		}
		else if (WeaponString == "Carbine Rifle")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.CarbineRifle, equipNow: true);
		}
		else if (WeaponString == "Pump Action Shotgun")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.PumpShotgun, equipNow: true);
		}
		else if (WeaponString == "Assault Shotgun")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.AssaultShotgun, equipNow: true);
		}
		else if (WeaponString == "Compact Grenade Launcher")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.CompactGrenadeLauncher, equipNow: true);
		}
		else if (WeaponString == "Micro SMG")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.MicroSMG, equipNow: true);
		}
		else if (WeaponString == "Heavy Pistol")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.HeavyPistol, equipNow: true);
		}
		else if (WeaponString == "AP Pistol")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.APPistol, equipNow: true);
		}
		else if (WeaponString == "Sniper Rifle")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.SniperRifle, equipNow: true);
		}
		else if (WeaponString == "")
		{
			Game.Player.Character.Weapons.Select(WeaponHash.Pistol, equipNow: true);
		}
	}

