	private unsafe void PlayerModelSet()
	{
		if (CharacterHash == 1)
		{
			ulong num = (ulong)(long)Game.Player.Character.MemoryAddress;
			ulong num2 = *(ulong*)(num + 32);
			*(long*)(num2 + 24) = 225514697L;
			Config.SetValue("Character Customization", "Michael, Franklin, or Trevor (1, 2, 3)", CharacterHash);
			Config.Save();
		}
		else if (CharacterHash == 2)
		{
			ulong num3 = (ulong)(long)Game.Player.Character.MemoryAddress;
			ulong num4 = *(ulong*)(num3 + 32);
			*(long*)(num4 + 24) = 2602752943L;
			Config.SetValue("Character Customization", "Michael, Franklin, or Trevor (1, 2, 3)", CharacterHash);
			Config.Save();
		}
		else if (CharacterHash == 3)
		{
			ulong num5 = (ulong)(long)Game.Player.Character.MemoryAddress;
			ulong num6 = *(ulong*)(num5 + 32);
			*(long*)(num6 + 24) = 2608926626L;
			Config.SetValue("Character Customization", "Michael, Franklin, or Trevor (1, 2, 3)", CharacterHash);
			Config.Save();
		}
	}

	private unsafe void PlayerModelSetBack()
	{
		if (CharacterGender == 1)
		{
			ulong num = (ulong)(long)Game.Player.Character.MemoryAddress;
			ulong num2 = *(ulong*)(num + 32);
			*(long*)(num2 + 24) = 1885233650L;
		}
		else if (CharacterGender == 2)
		{
			ulong num3 = (ulong)(long)Game.Player.Character.MemoryAddress;
			ulong num4 = *(ulong*)(num3 + 32);
			*(long*)(num4 + 24) = 2627665880L;
		}
	}

	private void FindModel()
	{
		Prop[] nearbyProps = World.GetNearbyProps(Game.Player.Character.Position, 3f);
		Prop[] array = nearbyProps;
		foreach (Prop prop in array)
		{
			World.DrawMarker(MarkerType.Sphere, prop.Position, Vector3.Zero, Vector3.Zero, new Vector3(0.35f, 0.35f, 35f), Color.LightBlue);
			if (Game.IsControlJustPressed(GTA.Control.VehicleDuck))
			{
				Notification.Show("P.Model" + prop.Model.GetHashCode());
			}
		}
	}

