			0, 1, 2, 3, 4, 5, 6, 8, 9, 10,
			11
		};
		Dictionary<int, Tuple<int, int>> dictionary = new Dictionary<int, Tuple<int, int>>();
		foreach (int item3 in list)
		{
			int item = Function.Call<int>(Hash.GET_PED_DRAWABLE_VARIATION, new InputArgument[2] { _ped, item3 });
			int item2 = Function.Call<int>(Hash.GET_PED_TEXTURE_VARIATION, new InputArgument[2] { _ped, item3 });
			Tuple<int, int> value = new Tuple<int, int>(item, item2);
			dictionary.Add(item3, value);
		}
		if (dictionary.Count > 0)
		{
			return dictionary;
		}
		return null;
	}

