	private void ArmEnemyPeds()
	{
		if (pedList.Count <= 0)
		{
			return;
		}
		foreach (Ped ped in pedList)
		{
			if (ped != null)
			{
				Function.Call(Hash.SET_PED_COMBAT_ABILITY, new InputArgument[2] { ped, 2 });
				Function.Call(Hash.SET_PED_COMBAT_MOVEMENT, new InputArgument[2] { ped, 1 });
				ped.Weapons.Give(WeaponHash.Pistol, 1000, equipNow: true, isAmmoLoaded: true);
				ped.Armor = 100;
				ped.AddBlip();
				ped.AttachedBlip.Sprite = BlipSprite.Enemy;
				ped.AttachedBlip.Color = BlipColor.Red;
				ped.AttachedBlip.Name = "Enemy";
				ped.RelationshipGroup = AiTeam;
			}
		}
	}

	private void CheckEnemyPeds()
	{
		if (pedList.Count <= 0)
		{
			return;
		}
		foreach (Ped item in pedList.ToList())
		{
			if (item != null && item.IsDead)
			{
				if (item.AttachedBlip != null)
				{
					item.AttachedBlip.Delete();
				}
				item.MarkAsNoLongerNeeded();
				pedList.Remove(item);
			}
			if (!(item != null))
			{
				continue;
			}
			if (Game.Player.Character.Position.DistanceTo(item.Position) < 20f)
			{
				if (item.AttachedBlip != null)
				{
					item.AttachedBlip.Alpha = 255;
				}
			}
			else if (Game.Player.Character.Position.DistanceTo(item.Position) > 20f && item.AttachedBlip != null)
			{
				item.AttachedBlip.Alpha = 0;
			}
		}
	}

	private void RemoveEnemyPeds()
	{
		if (pedList.Count <= 0)
		{
			return;
		}
		foreach (Ped item in pedList.ToList())
		{
			if (item != null && item.AttachedBlip != null)
			{
				item.AttachedBlip.Delete();
				item.Delete();
				pedList.Remove(item);
			}
		}
	}

	private void RemoveVehicles()
	{
		if (vehicleList.Count <= 0)
		{
			return;
		}
		foreach (Vehicle item in vehicleList.ToList())
		{
			if (item != null)
			{
				if (item.AttachedBlip != null)
				{
					item.AttachedBlip.Delete();
				}
				item.Delete();
				vehicleList.Remove(item);
			}
		}
	}

	private void TaskEnemyPeds()
	{
		if (pedList.Count <= 0)
		{
			return;
		}
		foreach (Ped item in pedList.ToList())
		{
			if (item != null)
			{
				item.Task.FightAgainstHatedTargets(playersTeam);
				item.AlwaysKeepTask = true;
				item.BlockPermanentEvents = true;
			}
		}
	}

