	private static void DriverSpeed(Ped p, Vehicle v)
	{
		if (!(v != null) || !(p != null) || v.Driver.Handle != p.Handle)
		{
			return;
		}
		float roadSpeed = GetRoadSpeed(v.Position + v.Velocity);
		if (roadSpeed != Speed)
		{
			float num = 0.01f;
			Speed = roadSpeed;
			if (v.Speed > Speed)
			{
				p.MaxDrivingSpeed = v.Speed - num * Game.LastFrameTime;
				p.DrivingSpeed = v.Speed - num * Game.LastFrameTime;
			}
			else
			{
				p.MaxDrivingSpeed = Speed;
				p.DrivingSpeed = Speed;
			}
		}
	}

	public static float GetRoadSpeed(Vector3 pos)
	{
		OutputArgument outputArgument = new OutputArgument();
		OutputArgument outputArgument2 = new OutputArgument();
		if (Function.Call<bool>(Hash.GET_VEHICLE_NODE_PROPERTIES, new InputArgument[5] { pos.X, pos.Y, pos.Z, outputArgument, outputArgument2 }))
		{
			int result = outputArgument.GetResult<int>();
			int result2 = outputArgument2.GetResult<int>();
			float num = 8f;
			foreach (PathnodeFlags item in Enum.GetValues(typeof(PathnodeFlags)).Cast<PathnodeFlags>())
			{
				if (((uint)item & (uint)result2) != 0)
				{
					num = item switch
					{
						PathnodeFlags.Two => 16f, 
						PathnodeFlags.Freeway => 35f, 
						PathnodeFlags.Slow => 25f, 
						PathnodeFlags.Eight => 16f, 
						PathnodeFlags.SlowTraffic => 25f, 
						PathnodeFlags.FourWayIntersection => 25f, 
						PathnodeFlags.Intersection => 25f, 
						_ => 35f, 
					};
				}
			}
			int num2 = Function.Call<int>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_ID, new InputArgument[7] { pos.X, pos.Y, pos.Z, 1, 1, 200f, 200f });
			if (Function.Call<bool>(Hash.GET_VEHICLE_NODE_IS_SWITCHED_OFF, new InputArgument[1] { num2 }) && num > 9f)
			{
				num *= 0.7f;
			}
			return num;
		}
		return 5f;
	}

