	private void Copy_Ped()
	{
		if (Copy == null)
		{
			Copy = Game.Player.Character.Clone(false);
		}
		if (Copy != null)
		{
			Copy.RelationshipGroup = playersTeam;
			Copy.IsInvincible = true;
			Copy.CanSwitchWeapons = true;
			Copy.Weapons.Give(WeaponHash.CombatMGMk2, 10000, equipNow: true, isAmmoLoaded: true);
			Copy.Weapons.Give(WeaponHash.MicroSMG, 10000, equipNow: true, isAmmoLoaded: true);
			int num = Function.Call<int>(Hash.GET_PED_GROUP_INDEX, new InputArgument[1] { Game.Player.Character });
			Function.Call(Hash.SET_PED_AS_GROUP_MEMBER, new InputArgument[2] { Copy, num });
			Function.Call(Hash.SET_PED_NEVER_LEAVES_GROUP, new InputArgument[2] { Copy, true });
			Copy.FiringPattern = FiringPattern.FullAuto;
		}
		if (Copy != null && !CopyBlip)
		{
			Copy.AddBlip();
			Copy.AttachedBlip.Sprite = BlipSprite.Standard;
			Copy.AttachedBlip.Color = BlipColor.Blue;
			Copy.AttachedBlip.Name = "Jim";
			CopyBlip = true;
		}
		else if (Copy != null && CopyBlip)
		{
			CopyBlip = true;
		}
	}

	private void XPController()
	{
		Ped[] nearbyPeds = World.GetNearbyPeds(Game.Player.Character.Position, 500f);
		Ped[] array = nearbyPeds;
		foreach (Ped ped in array)
		{
			if (ped.IsDead && !DeadBois.Contains(ped))
			{
				Entity killer = ped.Killer;
				if (killer is Ped && killer as Ped == Game.Player.Character)
				{
					DeadBois.Add(ped);
					EXP += 25;
					Config.SetValue("Level", "EXP", EXP);
					Config.Save();
					Wallet += 15;
					Config.SetValue("Level", "Wallet", Wallet);
					Config.Save();
					break;
				}
			}
		}
		foreach (Ped item in DeadBois.ToList())
		{
			if (item == null || !item.Exists())
			{
				DeadBois.Remove(item);
			}
		}
	}

	public static float CurrentExpLvl(float exp)
	{
		float num = 0.04f;
		return (float)((double)num * Math.Sqrt(exp));
	}

