			}
			if (Simeon != null)
			{
				Simeon.Delete();
			}
			if (BeginOnline != null)
			{
				BeginOnline.Delete();
			}
			if (IntroCar != null)
			{
				IntroCar.Delete();
			}
			IntroDriveMusic.Stop();
			IntroductionMusic.Stop();
			if (IntroCamCar != null)
			{
				IntroCamCar.Delete();
			}
			if (CamProp != null)
			{
				CamProp.Delete();
			}
			if (missionBlip != null)
			{
				missionBlip.Delete();
			}
			Game.Player.Character.IsVisible = true;
			Game.Player.CanControlCharacter = true;
			World.DestroyAllCameras();
			HudandRadar(Hud: true, Radar: true);
			World.RenderingCamera = null;
			Function.Call(Hash.SET_ARTIFICIAL_LIGHTS_STATE, new InputArgument[1] { false });
			Function.Call(Hash.PAUSE_CLOCK, new InputArgument[1] { false });
			Function.Call(Hash.SET_NIGHTVISION, new InputArgument[1] { false });
			Function.Call(Hash.SET_AUDIO_FLAG, new InputArgument[2] { "WantedMusicDisabled", false });
			Function.Call(Hash.TRIGGER_MUSIC_EVENT, new InputArgument[1] { "GTA_ONLINE_STOP_SCORE" });
		}
	}

	private void onKeyDown(object sender, KeyEventArgs e)
	{
		if (e.KeyCode == Keys.Delete && DEBUG)
		{
			Function.Call(Hash.STOP_CUTSCENE_IMMEDIATELY, Array.Empty<InputArgument>());
			if (Game.IsWaypointActive)
			{
				Vector3 waypointPosition = World.WaypointPosition;
				float groundHeight = World.GetGroundHeight(waypointPosition);
				World.GetSafeCoordForPed(waypointPosition, sidewalk: false);
				if (Game.Player.Character.CurrentVehicle == null)
				{
					Game.Player.Character.Position = waypointPosition;
				}
				else if (Game.Player.Character.CurrentVehicle != null)
				{
					Game.Player.Character.CurrentVehicle.Position = waypointPosition;
				}
			}
			if (!Game.IsWaypointActive)
			{
				Notification.Show("Waypoint not set");
			}
		}
		if (e.KeyCode == Keys.J)
		{
			GTA.UI.Screen.FadeIn(300);
			if (!Function.Call<bool>(Hash.HAS_CUTSCENE_FINISHED, Array.Empty<InputArgument>()) && Game.IsControlPressed(GTA.Control.VehicleHandbrake))
			{
				Function.Call(Hash.STOP_CUTSCENE, new InputArgument[1] { true });
			}
			if (DEBUG && Game.Player.Character != null)
			{
				Function.Call(Hash.TRIGGER_MUSIC_EVENT, new InputArgument[1] { "GTA_ONLINE_STOP_SCORE" });
				Thread thread;
				if (Game.Player.Character.IsInVehicle())
				{
					Notification.Show(Game.Player.Character.CurrentVehicle.IsSeatFree(VehicleSeat.LeftRear).ToString());
					Notification.Show(Function.Call<int>(Hash.GET_VEHICLE_MODEL_NUMBER_OF_SEATS, new InputArgument[1] { Game.Player.Character.CurrentVehicle.Model.Hash }).ToString());
					if (Game.Player.Character.CurrentVehicle != null)
					{
						Notification.Show(Game.Player.Character.CurrentVehicle.Model.Hash.ToString() ?? "");
					}
					thread = new Thread(() =>
					{
						Clipboard.SetText(Game.Player.Character.CurrentVehicle.Position.X + "f, " + Game.Player.Character.CurrentVehicle.Position.Y + "f, " + Game.Player.Character.CurrentVehicle.Position.Z + "f, " + Game.Player.Character.CurrentVehicle.Heading);
					});
				}
				else
				{
					Notification.Show(Game.Player.Character.Model.Hash.ToString() ?? "");
					Function.Call(Hash.STOP_CUTSCENE, Array.Empty<InputArgument>());
					thread = new Thread(() =>
					{
						Clipboard.SetText(Game.Player.Character.Position.X + "f, " + Game.Player.Character.Position.Y + "f, " + Game.Player.Character.Position.Z + "f, " + Game.Player.Character.Heading);
					});
				}
				thread.SetApartmentState(ApartmentState.STA);
				thread.Start();
				thread.Join();
			}
		}
		if (e.KeyCode == Keys.F5 && CellphoneIfruitSwitch == 1)
		{
			int num = Function.Call<int>(Hash.GET_RANDOM_INT_IN_RANGE, new InputArgument[2] { 0, 6 });
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { CELLPHONE_IFRUIT, "SET_SIGNAL_STRENGTH" });
			switch (num)
			{
			case 0:
				ScaleformINT(0);
				break;
			case 1:
				ScaleformINT(1);
				break;
			case 2:
				ScaleformINT(2);
				break;
			case 3:
				ScaleformINT(3);
				break;
			case 4:
				ScaleformINT(4);
				break;
			case 5:
				ScaleformINT(5);
				break;
			}
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { CELLPHONE_IFRUIT, "SET_THEME" });
			ScaleformINT(1);
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { CELLPHONE_IFRUIT, "SET_BACKGROUND_IMAGE" });
			ScaleformINT(Function.Call<int>(Hash.TO_FLOAT, new InputArgument[1] { 0 }));
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { CELLPHONE_IFRUIT, "SET_SLEEP_MODE" });
			ScaleformBOOL(uParam0: false);
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { CELLPHONE_IFRUIT, "DISPLAY_VIEW" });
			ScaleformFLOAT(1f);
			ScaleformINT(Function.Call<int>(Hash.TO_FLOAT, new InputArgument[1] { 0 }));
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, new InputArgument[2] { CELLPHONE_IFRUIT, "SET_SOFT_KEYS" });
			func_string_parm("joe");
			Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD, Array.Empty<InputArgument>());
			Function.Call(Hash.PLAY_SOUND_FRONTEND, new InputArgument[4] { -1, "Pull_Out", "Phone_SoundSet_Default", true });
			CellphoneIfruitSwitch = 2;
		}
	}

	public static void DisplayHelpText(string text)
	{
		InputArgument[] arguments = new InputArgument[1] { "STRING" };
		Function.Call(Hash.BEGIN_TEXT_COMMAND_DISPLAY_HELP, arguments);
		InputArgument[] arguments2 = new InputArgument[1] { text };
		Function.Call(Hash.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME, arguments2);
		InputArgument[] arguments3 = new InputArgument[4] { 0, 0, 1, -1 };
		Function.Call(Hash.END_TEXT_COMMAND_DISPLAY_HELP, arguments3);
	}
}
